// ═══ ITERATOR: forward-only ═══
List<String> list = List.of("A", "B", "C");
Iterator<String> it = list.iterator();
while (it.hasNext()) {
    String s = it.next();    // forward only!
    // it.remove();           // only removal (on modifiable list)
    // NO: it.add(), it.set(), it.previous()
}

// ═══ LISTITERATOR: bidirectional + add/set ═══
List<String> accounts = new ArrayList<>(List.of("A", "B", "D"));
ListIterator<String> lit = accounts.listIterator(2);  // start before "D"

lit.add("C");            // insert C before D → [A, B, C, D]
lit.previous();          // go back to C
lit.set("C-modified");   // replace C → [A, B, C-modified, D]
lit.previousIndex();     // 1 (index before current)
lit.nextIndex();         // 2 (index after current)

// ═══ COMPARISON TABLE ═══
// Feature              Iterator           ListIterator
// Works on             any Collection     List only
// Direction            forward only       forward + backward
// remove()             ✅                 ✅
// add()                ❌                 ✅ (inserts at position)
// set()                ❌                 ✅ (replaces last returned)
// nextIndex()          ❌                 ✅
// previousIndex()      ❌                 ✅
// Start at index       ❌                 ✅ listIterator(index)
