package com.bank.iterator;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class IteratorVsListIteratorTest {

    @Test
    void listIterator_bidirectional() {
        List<String> list = new ArrayList<>(List.of("A", "B", "C"));
        ListIterator<String> lit = list.listIterator(list.size());  // start at END

        List<String> reversed = new ArrayList<>();
        while (lit.hasPrevious()) {
            reversed.add(lit.previous());  // traverse BACKWARD!
        }
        assertThat(reversed).containsExactly("C", "B", "A");
    }

    @Test
    void listIterator_addDuringIteration() {
        List<String> list = new ArrayList<>(List.of("A", "C"));
        ListIterator<String> lit = list.listIterator(1);  // before "C"
        lit.add("B");  // insert B before C — NO CME!
        assertThat(list).containsExactly("A", "B", "C");
    }

    @Test
    void listIterator_setDuringIteration() {
        List<String> list = new ArrayList<>(List.of("A", "b", "C"));
        ListIterator<String> lit = list.listIterator();
        while (lit.hasNext()) {
            String s = lit.next();
            lit.set(s.toUpperCase());  // replace with uppercase — NO CME!
        }
        assertThat(list).containsExactly("A", "B", "C");
    }

    @Test
    void listIterator_indices() {
        List<String> list = List.of("A", "B", "C");
        ListIterator<String> lit = list.listIterator(1);  // before "B"
        assertThat(lit.previousIndex()).isEqualTo(0);
        assertThat(lit.nextIndex()).isEqualTo(1);
    }
}
