class LedgerEditor {
    List<LedgerEntry> entries = new LinkedList<>();

    void reconcile() {
        ListIterator<LedgerEntry> it = entries.listIterator();
        while (it.hasNext()) {
            int idx = it.nextIndex();
            LedgerEntry e = it.next();
            if (e.isStale())      it.remove();          // safe remove
            else if (e.needsFix())it.set(e.corrected()); // replace
            if (e.needsAdjustment())
                it.add(new LedgerEntry("ADJ", e.id()));  // insert
        }
    }
    // backward pass — ONLY ListIterator supports this
    void rollbackScan() {
        ListIterator<LedgerEntry> it = entries.listIterator(entries.size());
        while (it.hasPrevious()) audit(it.previous());
    }
    // plain Iterator: hasNext/next/remove only — forward, no add/set
}
